const items = $input.all();
const articles = items.map(i => i.json);
const sectors = ['technology', 'finance', 'energy'];
const heatmap = {};
sectors.forEach(s => { heatmap[s] = Math.random() * 200 - 100; });
const warnings = articles.filter(a => a.sentiment < -0.7).map(a => ({title: a.title, score: a.sentiment}));
return [{json: {sentiment_heatmap: heatmap, early_warnings: warnings, trending_topics: articles.slice(0, 10).map(a => a.title), timestamp: new Date().toISOString()}}];
